message.content:
{
  "technical_and_design_decisions": [
    "Baseline on Spring XD 1.0 codebase and deliver increment as XD 1.1.",
    "Implement Spark Streaming data processors as a new XD module using Java (with lambdas) and Scala, built via Maven Scala plugin.",
    "Enable Windows builds by fixing Maven/Gradle scripts and removing Unix-specific assumptions.",
    "For Kafka upgrade, backport XD-specific changes to Spring Integration Kafka project, then depend on the GA release.",
    "Upgrade Spring Hadoop (SHDP) to GA and adapt configuration and APIs accordingly.",
    "Provision Windows acceptance test environment on AWS EC2 and configure Jenkins CI jobs.",
    "Maintain Java 7/8 compatibility consistent with the XD 1.1 era (not Java 17).",
    "Provide Pig job integration sample as a reference module under XD samples."
  ],
  "assumptions": [
    "A single developer performs all work; effort estimates represent personal workdays (8-hour days).",
    "Existing XD 1.0 codebase builds and tests on Linux; Windows support is net-new effort.",
    "Required GA artifacts for Kafka SI and SHDP are available and compatible with the targeted XD 1.1 release.",
    "Acceptance test suite already exists; effort covers environment setup and execution, not authoring new tests.",
    "AWS EC2 Windows image can be provisioned with necessary toolchain (Java, Maven, etc.) within estimated effort.",
    "Spark version targeted is compatible with Java 8 and Scala 2.10/2.11.",
    "Migration from 1.0 to 1.1 primarily requires API stabilization, compatibility shims, and documentation, not a full rewrite."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "XD 1.0 to 1.1 migration support",
      "activity_description": "Analyze 1.0 custom module APIs, define migration path, provide backward compatibility shims and migration guide for users to port custom modules (U1).",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A2",
      "activity_name": "Pig job sample",
      "activity_description": "Create a reference Pig script/job sample module and documentation showing how to integrate Pig jobs in XD (U2).",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A3",
      "activity_name": "Windows build enablement",
      "activity_description": "Modify build scripts and environment setup to allow building XD on a Windows machine for development and testing (U3).",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A4",
      "activity_name": "Windows acceptance test CI",
      "activity_description": "Provision Windows EC2 image, execute existing acceptance test coverage, and set up CI build to run tests on Windows (U4).",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A5",
      "activity_name": "Spark Streaming processors",
      "activity_description": "Implement Spark Streaming as data processors in XD using Java/Java Lambdas and Scala, including integration, unit/integration tests, and basic sample (U5).",
      "most_likely_effort": 15
    },
    {
      "activity_id": "A6",
      "activity_name": "Copyright update in reference guide",
      "activity_description": "Update copyright message in the reference guide source so generated PDF includes 2015 instead of 2014 (U6).",
      "most_likely_effort": 0.5
    },
    {
      "activity_id": "A7",
      "activity_name": "Kafka SI GA upgrade",
      "activity_description": "Backport Kafka XD changes to Spring Integration Kafka, then upgrade XD to use the Kafka SI GA release and adapt code/tests (U7).",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A8",
      "activity_name": "SHDP GA upgrade",
      "activity_description": "Upgrade XD to use Spring Hadoop (SHDP) GA release, adjusting configurations and code for API changes, and test Hadoop integrations (U8).",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A9",
      "activity_name": "Integration and release",
      "activity_description": "Perform cross-cutting integration testing of all new features, fix defects, build final release artifacts, and write release notes.",
      "most_likely_effort": 6
    }
  ],
  "reported_total": {
    "most_likely_effort": 56.5
  }
}

